script:
frappe.ui.form.on('Leave Application', {
	refresh(frm) {
		// your code here
	},
	to_date(frm) {
	    adjust_deducted_leave_days(frm);
    },
    half_day(frm) {
        adjust_deducted_leave_days(frm);
    }
});

function adjust_deducted_leave_days(frm) {

    if (!frm.doc.leave_type) return;

    frappe.call({
            method: "frappe.client.get_value",
            args: {
                doctype: "Leave Type",
                filters: {
                    name: frm.doc.leave_type
                },
                fieldname: [
                    "custom_apply_rotational_multiplier"
                ]
            },
            callback(r) {
                const multiplier = r.message.custom_apply_rotational_multiplier ? 2 : 1;
                const total = frm.doc.total_leave_days || 0;

                frm.set_value("custom_deducted_leave_days", total * multiplier || 1);
            }
        });


}

frappe.ui.form.on('Leave Policy', {
	refresh(frm) {
		calculate_total_leave_days(frm);
	}
})

frappe.ui.form.on('Leave Policy Detail', {
	refresh(frm) {
		// your code here
	},
	annual_allocation(frm, cdt, cdn) {
        calculate_total_leave_days(frm);
    },

    leave_policy_details_remove(frm) {
        calculate_total_leave_days(frm);
    }
});

function calculate_total_leave_days(frm) {
    let total = 0;

    (frm.doc.leave_policy_details || []).forEach(row => {
        total += flt(row.annual_allocation || 0);
    });

    frm.set_value("custom_total_leave_days", total);
}
